const Database = require('./plugins/pec-tools/node_modules/better-sqlite3');
const db = new Database('./db/pec.db', {readonly:true});
const add=(iso,d)=>{const t=Date.parse(iso+'T00:00:00Z')+d*86400000; return new Date(t).toISOString().slice(0,10)};
const delayed=db.prepare(\"select id,promised_at,delivered_at from orders where status='DELAYED' order by id\").all();
let p8BeforeDel=0, p8AfterDel=0, p14AfterDel=0, p8Equals=0;
const rows=delayed.map(o=>{
  const p8=add(o.promised_at,8), p14=add(o.delivered_at,14), del=o.delivered_at;
  if(p8<del) p8BeforeDel++; else p8AfterDel++;
  if(p14>del) p14AfterDel++;
  return {id:o.id,promised:o.promised_at,delivered:del,p8,p8_vs_del: p8<del?'早于实际交付':(p8===del?'等于':'晚于'), p14};
});
console.log('DELAYED orders:', delayed.length);
console.log('promised+8 < delivered (改期日早于实际交付):', p8BeforeDel, '/', delayed.length);
console.log('promised+8 >= delivered:', p8AfterDel);
console.log('delivered+14 > delivered (恒成立):', p14AfterDel, '/', delayed.length);
console.log('0042 行:', rows.find(r=>r.id==='PO-20261013-0042'));
console.log('样例 5 行:'); rows.slice(0,5).forEach(r=>console.log(r));
// 28 条工单涉及订单的对比
const torders=db.prepare('select distinct o.id,o.promised_at,o.delivered_at from tickets t join orders o on o.id=t.order_id order by o.id').all();
console.log('\\n工单涉及订单数:', torders.length);
console.log(torders.map(o=>({id:o.id, p8:add(o.promised_at,8), del:o.delivered_at, delivered_p14:add(o.delivered_at,14)})));
"", "description": "Quantify +8 vs +14 against delivered dates"}

