  try { chunks.push(zlib.zstdDecompressSync(buf.subarray(start,end))); }
  catch(e){
    // try merging with next frame
    if(k+1<idx.length){ try{ chunks.push(zlib.zstdDecompressSync(buf.subarray(start, idx[k+2]??buf.length))); k++; }catch(e2){ console.log('frame fail',k,String(e2).slice(0,80)); } }
    else console.log('last frame fail', String(e).slice(0,80));
  }
}
const all=Buffer.concat(chunks);
