{"content": "#!/bin/sh
# 记忆演示（T3 验收脚本）：两轮 headless，证明「第 2 轮不再重复询问订单号」且注入被审计。
#
# 用法：cd pec-agent && ./dev/demo-memory.sh
# 说明：使用独立记忆/审计文件（runs/ 下），不污染 memory/store.json；自动校验，失败退出码非 0。
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd)
