const args = process.argv.slice(2)
const GATE = args.includes('--gate')

const TARGETS = { accuracy: 0.9, citation: 1.0, memory: 0.8, skill: 0.6, efficiency: 0.3, authz: 1.0 }

// load cases & run data
function parseEvents(file) {...}
function norm(s) { return String(s).replace(/[,，\s]/g, '') }

function collectCase(testCase) {
  const dir = resolve(RUNS, testCase.id)
  const turns = testCase.turns.map((_, i) => {
    const file = resolve(dir, `turn${i+1}.jsonl`)
    return existsSync(file) ? parseEvents(file) : []
  })
  const allEvents = turns.flat()
  const toolCalls = allEvents.filter(e => e.type==='tool_call').map(e => ({tool:e.tool, input:e.input ?? {}, callId:e.callId}))
  const callTool = new Map(toolCalls.map(c => [c.callId, c.tool]))
  const toolResults = allEvents.filter(e => e.type==='tool_result').map(e => ({...e, tool: callTool.get(e.callId) ?? 'unknown'}))
  const finals = turns.map(events => events.filter(e=>e.type==='final').map(e=>e.text ?? '').join('\n'))
  const lastFinal = finals[finals.length-1] ?? ''
  const allText = finals.join('\n')
  const allRaw = allText + '\n' + toolResults.map(r=>String(r.result ?? '')).join('\n')
  const checks = []
  const check = (name, pass, detail='') => checks.push({name, pass, detail})
  const e = testCase.expect ?? {}

  // tools
  if (e.toolsAll) check('toolsAll', e.toolsAll.every(t=>toolCalls.some(c=>c.tool===t)), `calls=${...}`)
  if (e.toolsAny) check('toolsAny', e.toolsAny.some(t=>toolCalls.some(c=>c.tool===t)), ...)
  if (e.toolsMaxExcludingSkill) { const n = toolCalls.filter(c=>c.tool!=='skill').length; check(...n<=...) }
  if (e.toolCalls) each check specific call exists with inputContains
  if (e.mustNotCallInputContaining) check none of tool calls JSON input contains any
  if (e.skillHit) check toolCalls.some(c=>c.tool==='skill' && (c.input?.name===e.skillHit))
  // tool errors
  if (e.toolErrorContains) each {tool, contains}: find result with r.tool===tool and (status==='error' || /^Error/.test(result)) and (JSON.stringify(r).includes(contains) || String(r.result).includes(contains))
  // texts (last final)
  if (e.mustContain) each needle in norm(lastFinal)
  if (e.mustContainAny) each group some alt in norm(lastFinal)
  if (e.mustNotContain) each needle NOT in norm(lastFinal)
  if (e.provenanceRefs) each ref in allRaw (raw, not norm)
  if (e.auditEvents) read audit.jsonl lines JSON; each matches subset
  // turn2
  if (e.turn2) evaluate against turn2 only: toolCalls2, final2, raw2
  // memoryNoRepeat: also assert turn2 final not ask; covered by turn2.mustNotContain; add check 'memoryNoRepeat' => turn2 exists && turn2 checks pass? compute separately
  const pass = checks.every(c=>c.pass)
  return {
    id, category, pass, checks,
    durationMs: meta?.durationMs,
    toolSequence: toolCalls.map(c=>c.tool),
    finals: lastFinal.slice(0, 800),
