function norm(s) { return String(s).replace(/[,，\s]/g, '') }

function collectCase(testCase) {
  const dir = resolve(RUNS, testCase.id)
  const turns = testCase.turns.map((_, i) => {
    const file = resolve(dir, `turn${i+1}.jsonl`)
    return existsSync(file) ? parseEvents(file) : []
  })
  const allEvents = turns.flat()
  const toolCalls = allEvents.filter(e => e.type==='tool_call').map(e => ({tool:e.tool, input:e.input ?? {}, callId:e.callId}))
  const callTool = new Map(toolCalls.map(c => [c.callId, c.tool]))
  const toolResults = allEvents.filter(e => e.type==='tool_result').map(e => ({...e, tool: callTool.get(e.callId) ?? 'unknown'}))
  const finals = turns.map(events => events.filter(e=>e.type==='final').map(e=>e.text ?? '').join('\n'))
  const lastFinal = finals[finals.length-1] ?? ''
  const allText = finals.join('\n')
  const allRaw = allText + '\n' + toolResults.map(r=>String(r.result ?? '')).join('\n')
  const checks = []
