  lines.push(`| ${index + 1} | ${result.id} | ${result.category} | ${result.pass ? 'PASS' : 'FAIL'} | ${sequence} | ${result.durationMs ? `${(result.durationMs / 1000).toFixed(1)}s` : '-'} | ${failed} |`)
})
